vec3 s = std::normalize(std::cross(f, std::normalize(up)));
vec3 u = std::cross(s, f);

mat4 result(1.0f);
result[0][0] = s.x; result[0][1] = s.y; result[0][2] = s.z; result[0][3] = 0.0f;
result[1][0] = u.x; result[1][1] = u.y; result[1][2] = u.z; result[1][3] = 0.0f;
result[2][0] = -f.x; result[2][1] = -f.y; result[2][2] = -f.z; result[2][3] = 0.0f;
result[3][0] = 0.0f; result[3][1] = 0.0f; result[3][2] = 0.0f; result[3][3] = 1.0f;

result = std::translate(mat4(1.0f), -eye) * result;
return result;
